<script lang="ts">
  import type { PresentedScannerAction } from "../../../src/core/action-presentation";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";

  let { runtime, actions }: {
    runtime: SvelteScannerRuntime<unknown>;
    actions: readonly PresentedScannerAction[];
  } = $props();
</script>

{#if actions.length}
  <div class="qrs-prompt-actions zombie-warning__actions">
    {#each actions as action, index (action.id)}
      {#if index > 0}<span aria-hidden="true">|</span>{/if}
      <button
        type="button"
        data-qrs-action={action.id}
        data-qrs-kind={action.kind}
        data-tone={action.tone}
        disabled={action.disabled}
        aria-label={action.label}
        onclick={() => runtime.triggerPresentedAction(action)}
      >{action.promptLabel}</button>
    {/each}
  </div>
{/if}
