<script lang="ts">
  import type { ScannerState } from "../../../src/core/types";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";
  import type { ScannerSurfaceState } from "../runtime/types";
  import PromptActions from "./PromptActions.svelte";

  let { runtime, state, surface }: {
    runtime: SvelteScannerRuntime<unknown>;
    state: Readonly<ScannerState<unknown>>;
    surface: Readonly<ScannerSurfaceState>;
  } = $props();
</script>

<div
  class:qr-assign={state.status?.layout === "confirmation"}
  class="qrs-status qr-scanner__prompt"
  role="status"
  aria-live="polite"
  data-tone={state.status?.tone}
  hidden={!state.status || Boolean(surface.dialog)}
>
  {#if state.status}
    <div class:qrs-prompt-copy--aligned={state.status.layout === "diagnostic"} class="qrs-prompt-copy">{state.status.text}</div>
    {#if state.status.detail}<small class="qrs-prompt-secondary">{state.status.detail}</small>{/if}
    {#if state.status.note}<div class="qrs-prompt-secondary qr-scanner__prompt-note">{state.status.note}</div>{/if}
    {#if !surface.dialog}<PromptActions {runtime} actions={surface.promptActions} />{/if}
  {/if}
</div>

<div
  class="qrs-result qr-scanner__prompt"
  role="status"
  aria-live="polite"
  hidden={!surface.resultText || Boolean(surface.dialog)}
>
  <span class="qrs-result__payload qrs-prompt-copy">{surface.resultText ?? ""}</span>
</div>

<div
  class="qrs-dialog qr-scanner__prompt zombie-warning"
  role="presentation"
  data-delete-step={surface.dialog?.deleteStep}
  hidden={!surface.dialog}
>
  {#if surface.dialog}
    <div
      class="qrs-dialog__panel zombie-warning__dialog"
      role="alertdialog"
      aria-modal="false"
      aria-label={surface.dialog.title || "Stale QR code warning"}
      tabindex="-1"
    >
      <h2 class="qrs-dialog__title qrs-prompt-copy zombie-warning__title">{surface.dialog.title}</h2>
      <p class="qrs-dialog__body qrs-prompt-secondary zombie-warning__message">{surface.dialog.body}</p>
      <PromptActions {runtime} actions={surface.promptActions} />
    </div>
  {/if}
</div>
