import { acquireCamera, applyTorchConstraint, profileFromTrack, requestFocusExposure, stopStream } from "../../../src/camera/media";
import {
  buildUnifiedModel,
  dialAngleToZoom,
  logicalToNativeZoom,
  logicalToSegment,
  probeCameras,
  type CameraProfile,
  type UnifiedZoomModel,
} from "../../../src/camera/zoom";
import type { QrDecoder } from "../../../src/decoder/types";
import { ZxingQrDecoder } from "../../../src/decoder/zxing";
import { mapDialogActions } from "../../../src/core/dialog-actions";
import {
  advanceDeleteStep,
  CONFIRM_DELETE_LABEL,
  isDeleteConfirming,
  type DeleteStep,
} from "../../../src/core/delete-confirmation";
import {
  mapDialogActionGroups,
  mapScannerActionControls,
  orderPresentedActions,
  resolveScannerPresentation,
  type PresentedScannerAction,
  type ResolvedScannerPresentation,
} from "../../../src/core/action-presentation";
import { clamp, clampRoi, coverRectToVideoRoi, defaultCenteredRoi, padRoiPixels, pinchZoneFrame, roiToRect, type Point } from "../../../src/core/geometry";
import { persistHandedness, readPersistedHandedness } from "../../../src/core/handedness";
import { LifecycleError } from "../../../src/core/lifecycle-error";
import { ResultPipeline } from "../../../src/core/result-pipeline";
import { CameraFeedBuildInfoGesture, formatBuildInfo } from "../../../src/core/build-info";
import type {
  QrScannerController,
  ResultListener,
  Roi,
  ScanContext,
  ScanResult,
  ScannerActionControls,
  ScannerCodePresentation,
  ScannerDialog,
  ScannerHandedness,
  ScannerOptions,
  ScannerPresentationOptions,
  ScannerState,
} from "../../../src/core/types";
import type {
  DialogRecord,
  PublicStateListener,
  ScannerSurfaceRefs,
  ScannerSurfaceState,
  SurfaceStateListener,
} from "./types";

type VideoFrameVideo = HTMLVideoElement & {
  requestVideoFrameCallback?: (callback: (now: number) => void) => number;
  cancelVideoFrameCallback?: (handle: number) => void;
};
type NumericCapability = { min: number; max: number; step?: number };
type TrackCapabilities = MediaTrackCapabilities & { zoom?: NumericCapability; torch?: boolean };
type Gesture = { primaryId: number; mode: "scan" | "pinch"; dragOffset: Point };

const TARGET_SCAN_INTERVAL_MS = 1000 / 30;
const TRY_HARDER_EVERY = 3;
const ROTATION_FALLBACK = [0, 90, 180, 270] as const;
const ANGLED_FALLBACK_AFTER_MISSES = 3;
const ANGLED_FALLBACK_INTERVAL_MS = 500;
const ROI_PADDING_RATIO = 0.12;
const TOUCH_GESTURE_GRACE_MS = 120;
const DEFAULT_ZOOM_MODEL = buildUnifiedModel([]);

const cloneState = <TValue>(state: ScannerState<TValue>): Readonly<ScannerState<TValue>> => Object.freeze({
  ...state,
  roi: { ...state.roi },
  zoomRange: { ...state.zoomRange },
});

const cloneSurface = (surface: ScannerSurfaceState): Readonly<ScannerSurfaceState> => Object.freeze({
  ...surface,
  code: { ...surface.code },
  actions: { ...surface.actions },
  promptActions: [...surface.promptActions],
  dialog: surface.dialog ? { ...surface.dialog } : null,
  cameras: [...surface.cameras],
  stage: { ...surface.stage },
  roi: { ...surface.roi },
});

export class SvelteScannerRuntime<TValue = string> extends EventTarget implements QrScannerController<TValue> {
  private readonly options: ScannerOptions<TValue>;
  private readonly pipeline: ResultPipeline<TValue>;
  private readonly decoder: QrDecoder;
  private readonly mediaDevices: MediaDevices | null;
  private readonly stateListeners = new Set<PublicStateListener<TValue>>();
  private readonly surfaceListeners = new Set<SurfaceStateListener>();
  private host: HTMLElement | null = null;
  private refs: ScannerSurfaceRefs | null = null;
  private stream: MediaStream | null = null;
  private track: MediaStreamTrack | null = null;
  private cameraRequest = 0;
  private profiles: CameraProfile[] = [];
  private zoomModel: UnifiedZoomModel = DEFAULT_ZOOM_MODEL;
  private activeSegment = DEFAULT_ZOOM_MODEL.segments[0]!;
  private frameHandle: number | null = null;
  private frameKind: "video" | "animation" | null = null;
  private decoding = false;
  private scanOwned = false;
  private scanRoi: Roi | null = null;
  private passiveZoomScan = false;
  private lastDecodeAt = 0;
  private lastAngleFallbackAt = 0;
  private decodeAttempt = 0;
  private consecutiveMisses = 0;
  private liveDecoded: string | null = null;
  private pointers = new Map<number, Point>();
  private readonly buildInfoGesture = new CameraFeedBuildInfoGesture();
  private readonly pendingTouchPointers = new Map<number, Point>();
  private pendingTouchTimer: ReturnType<typeof setTimeout> | null = null;
  private gesture: Gesture | null = null;
  private dialPointerId: number | null = null;
  private dialogRecord: DialogRecord | null = null;
  private dialogResolve: ((action: string) => void) | null = null;
  private deleteAnimationFallback: ReturnType<typeof setTimeout> | null = null;
  private actionControls: ScannerActionControls = {};
  private hostInputLocked = false;
  private actionPresentation = resolveScannerPresentation();
  private dialogPresentation: ResolvedScannerPresentation | null = null;
  private state: ScannerState<TValue>;
  private surface: ScannerSurfaceState;

  constructor(options: ScannerOptions<TValue> = {}) {
    super();
    this.options = options;
    this.mediaDevices = options.mediaDevices ?? globalThis.navigator?.mediaDevices ?? null;
    this.decoder = options.decoder ?? new ZxingQrDecoder();
    this.pipeline = new ResultPipeline<TValue>({
      normalizePayload: options.normalizePayload,
      handler: options.handler,
      onResult: options.onResult,
      historyLimit: options.historyLimit,
      target: this,
    });
    const handedness = options.handedness ?? readPersistedHandedness() ?? "right";
    const roi = { x: 0, y: 0, size: 180 };
    this.state = {
      lifecycle: "new",
      inputLocked: false,
      targeting: false,
      status: null,
      lastResult: null,
      cameraId: null,
      cameraLabel: null,
      cameraError: null,
      torch: false,
      torchSupported: false,
      handedness,
      zoom: 1,
      zoomSource: "software",
      zoomRange: { min: 1, max: 4, step: 0.01 },
      roi,
    };
    this.surface = {
      visible: false,
      scanning: false,
      focusPulse: 0,
      code: { code: null, state: "idle" },
      resultText: null,
      actions: {},
      promptActions: [],
      interactionGlass: false,
      dialog: null,
      cameraMenuOpen: false,
      cameras: [],
      stage: { width: 0, height: 0 },
      roi,
    };
  }

  subscribeState(listener: PublicStateListener<TValue>): () => void {
    this.stateListeners.add(listener);
    listener(this.getState());
    return () => this.stateListeners.delete(listener);
  }

  subscribeSurface(listener: SurfaceStateListener): () => void {
    this.surfaceListeners.add(listener);
    listener(this.getSurfaceState());
    return () => this.surfaceListeners.delete(listener);
  }

  getSurfaceState(): Readonly<ScannerSurfaceState> { return cloneSurface(this.surface); }

  attachSurface(refs: ScannerSurfaceRefs): this {
    this.refs = refs;
    if (this.stream) refs.video.srcObject = this.stream;
    return this;
  }

  detachSurface(): this {
    if (this.dialogRecord) this.dismissDialog("surface_detached");
    if (this.refs) this.refs.video.srcObject = null;
    this.refs = null;
    return this;
  }

  mount(host: HTMLElement): this {
    this.assertAlive();
    this.host = host;
    if (this.state.lifecycle === "new") this.patchState({ lifecycle: "mounted" });
    if (this.options.camera?.autoStart !== false) this.open();
    return this;
  }

  reparent(host: HTMLElement): this { this.assertAlive(); this.host = host; return this; }

  open(): this {
    this.assertAlive();
    if (!this.host) throw new Error("Mount the scanner before opening it.");
    this.patchSurface({ visible: true });
    if (this.state.lifecycle !== "open") this.patchState({ lifecycle: "open" });
    if (this.options.camera?.autoStart !== false && !this.stream) void this.startCamera();
    return this;
  }

  close(): this {
    if (this.isDestroyed()) return this;
    this.endScan(false);
    this.stopCamera();
    if (this.dialogRecord) this.dismissDialog("scanner_closed");
    this.patchSurface({ visible: false, cameraMenuOpen: false });
    this.patchState({ lifecycle: "closed" });
    return this;
  }

  pause(): this {
    this.assertAlive();
    this.endScan(false);
    if (this.state.lifecycle === "open") this.patchState({ lifecycle: "paused" });
    return this;
  }

  resume(): this {
    this.assertAlive();
    if (this.state.lifecycle === "paused") this.patchState({ lifecycle: "open" });
    return this;
  }

  destroy(): void {
    if (this.isDestroyed()) return;
    this.dismissDialog("scanner_destroyed");
    this.stopCamera();
    this.pipeline.destroy();
    this.decoder.destroy?.();
    this.detachSurface();
    this.host = null;
    this.patchSurface({ visible: false });
    this.patchState({ lifecycle: "destroyed" });
    this.stateListeners.clear();
    this.surfaceListeners.clear();
  }

  setInputLocked(locked: boolean): this {
    this.assertAlive();
    this.hostInputLocked = locked;
    this.syncPresentationState();
    return this;
  }

  setTargeting(active: boolean): this { this.assertAlive(); this.patchState({ targeting: active }); return this; }

  setStatus(status: ScannerState<TValue>["status"]): this {
    this.assertAlive();
    if (status) this.patchSurface({ resultText: null });
    this.patchState({ status });
    this.syncPresentationState();
    return this;
  }

  setCodePresentation(code: ScannerCodePresentation): this {
    this.assertAlive();
    this.patchSurface({ code, scanning: code.state === "preview" });
    return this;
  }

  setActionControls(actions: ScannerActionControls, presentation?: ScannerPresentationOptions): this {
    this.assertAlive();
    this.actionControls = actions;
    this.actionPresentation = resolveScannerPresentation(presentation);
    this.syncPresentationState();
    return this;
  }

  showDialog(dialog: ScannerDialog, presentation?: ScannerPresentationOptions): Promise<string> {
    this.assertAlive();
    if (this.dialogResolve) this.dismissDialog("superseded");
    const { left, right } = mapDialogActions(dialog);
    const deleteStep: DeleteStep = right?.tone === "delete" ? "idle" : "none";
    this.dialogRecord = {
      definition: dialog,
      left,
      right,
      originalBody: dialog.body,
      deleteStep,
    };
    this.dialogPresentation = resolveScannerPresentation(presentation, { mirrorActionsInPrompt: true });
    this.patchSurface({
      resultText: null,
      actions: {
        jump: null,
        cancel: left ? { id: left.id, label: left.label } : null,
        accept: right ? { id: right.id, label: right.label } : null,
      },
      dialog: {
        title: dialog.title,
        body: dialog.body,
        left,
        right,
        deleteStep,
        deleteAnimating: isDeleteConfirming(deleteStep),
      },
    });
    this.syncPresentationState();
    return new Promise((resolve) => { this.dialogResolve = resolve; });
  }

  dismissDialog(actionId = "dismissed"): this {
    if (this.deleteAnimationFallback !== null) clearTimeout(this.deleteAnimationFallback);
    this.deleteAnimationFallback = null;
    this.dialogRecord = null;
    this.dialogPresentation = null;
    this.patchSurface({ dialog: null, actions: this.actionControls });
    this.syncPresentationState();
    const resolve = this.dialogResolve;
    this.dialogResolve = null;
    resolve?.(actionId);
    if (resolve) this.dispatchEvent(new CustomEvent("dialogaction", { detail: { actionId } }));
    return this;
  }

  activateDialogAction(actionId: string): void {
    const record = this.dialogRecord;
    if (!record || isDeleteConfirming(record.deleteStep)) return;
    const action = [record.left, record.right].find((candidate) => candidate?.id === actionId);
    if (!action) return;
    if (action === record.right && action.tone === "delete") {
      const next = advanceDeleteStep(record.deleteStep);
      record.deleteStep = next;
      this.patchDialog({
        deleteStep: next,
        deleteAnimating: isDeleteConfirming(next),
        body: next === "armed"
          ? `${record.originalBody}\nSelect ${CONFIRM_DELETE_LABEL} to continue.`
          : this.surface.dialog?.body ?? record.originalBody,
      });
      if (isDeleteConfirming(next)) {
        this.deleteAnimationFallback = setTimeout(() => this.completeDeleteAnimation(), 1050);
      }
      return;
    }
    this.dismissDialog(action.id);
  }

  completeDeleteAnimation(): void {
    const record = this.dialogRecord;
    if (!record?.right || record.right.tone !== "delete" || !isDeleteConfirming(record.deleteStep)) return;
    if (this.deleteAnimationFallback !== null) clearTimeout(this.deleteAnimationFallback);
    this.deleteAnimationFallback = null;
    this.dismissDialog(record.right.id);
  }

  triggerAction(kind: "jump" | "accept" | "cancel"): void {
    const dialog = this.dialogRecord;
    if (dialog) {
      const action = kind === "cancel" ? dialog.left : kind === "accept" ? dialog.right : null;
      if (action) this.activateDialogAction(action.id);
      return;
    }
    const control = this.actionControls[kind];
    if (!control || control.disabled) return;
    this.dispatchEvent(new CustomEvent("action", { detail: { id: control.id, kind } }));
    if (this.actionPresentation.dismissAfterAction) {
      this.setStatus(null);
      this.setActionControls({});
      this.setTargeting(false);
    }
  }

  triggerPresentedAction(action: PresentedScannerAction): void {
    if (action.disabled) return;
    if (this.dialogRecord) {
      this.activateDialogAction(action.id);
      return;
    }
    this.triggerAction(action.kind);
  }

  requestClose(): void {
    if (this.dialogRecord) {
      if (this.dialogRecord.left) this.activateDialogAction(this.dialogRecord.left.id);
      else this.dismissDialog();
      return;
    }
    this.dispatchEvent(new Event("close"));
    this.close();
  }

  dismissResult(): this {
    this.patchSurface({ resultText: null, code: { code: null, state: "idle" } });
    return this;
  }

  async emitSynthetic(payload: string, context: Omit<ScanContext, "source"> = {}): Promise<ScanResult<TValue>> {
    this.assertAlive();
    return this.deliver(payload, { ...context, source: "synthetic" });
  }

  subscribe(listener: ResultListener<TValue>): () => void { return this.pipeline.subscribe(listener); }
  nextResult(): Promise<ScanResult<TValue>> { return this.pipeline.next(); }
  getLastResult(): ScanResult<TValue> | null { return this.pipeline.last(); }
  getHistory(): readonly ScanResult<TValue>[] { return this.pipeline.history(); }
  getState(): Readonly<ScannerState<TValue>> { return cloneState(this.state); }

  async enumerateCameras(): Promise<readonly MediaDeviceInfo[]> {
    if (!this.mediaDevices) return [];
    try {
      const cameras = (await this.mediaDevices.enumerateDevices()).filter((device) => device.kind === "videoinput");
      this.patchSurface({ cameras });
      return cameras;
    } catch (error) {
      this.reportCameraError(error);
      return [];
    }
  }

  toggleCameraMenu(): void {
    if (!this.stream) void this.startCamera();
    const cameraMenuOpen = !this.surface.cameraMenuOpen;
    this.patchSurface({ cameraMenuOpen });
    if (cameraMenuOpen) void this.enumerateCameras();
  }

  closeCameraMenu(): void { this.patchSurface({ cameraMenuOpen: false }); }

  async startCamera(deviceId?: string, requestedZoom?: number): Promise<void> {
    if (!this.mediaDevices || this.isDestroyed()) {
      if (!this.mediaDevices) this.reportCameraError(new Error("Camera APIs are unavailable in this browser."));
      return;
    }
    const request = ++this.cameraRequest;
    const wasScanning = this.scanOwned;
    if (wasScanning) this.cancelFrame();
    stopStream(this.stream);
    this.stream = null;
    this.track = null;
    if (this.refs) this.refs.video.srcObject = null;
    this.patchState({ cameraId: null, cameraLabel: null, cameraError: null, torch: false, torchSupported: false });
    try {
      const stream = await acquireCamera(this.mediaDevices, {
        deviceId: deviceId ?? this.options.camera?.deviceId,
        facingMode: this.options.camera?.facingMode,
        idealWidth: this.options.camera?.idealWidth,
        idealHeight: this.options.camera?.idealHeight,
      });
      if (this.isDestroyed() || request !== this.cameraRequest) { stopStream(stream); return; }
      this.stream = stream;
      this.track = stream.getVideoTracks()[0] ?? null;
      if (this.refs) {
        this.refs.video.srcObject = stream;
        try { await this.refs.video.play(); } catch { /* a user gesture may still be required */ }
      }
      if (!this.track) throw new Error("The camera stream contained no video track.");
      const profile = profileFromTrack(this.track);
      this.profiles = [profile];
      this.zoomModel = buildUnifiedModel(this.profiles, {
        allowSwitching: this.options.camera?.allowSwitching ?? true,
        primaryDeviceId: profile.deviceId,
      });
      this.activeSegment = logicalToSegment(requestedZoom ?? profile.settingsZoom ?? 1, this.zoomModel);
      const capabilities = (this.track.getCapabilities?.() ?? {}) as TrackCapabilities;
      this.patchState({
        cameraId: profile.deviceId,
        cameraLabel: profile.label || "Camera",
        cameraError: null,
        torchSupported: capabilities.torch === true,
        torch: false,
        zoom: clamp(requestedZoom ?? profile.settingsZoom ?? 1, this.zoomModel.range.min, this.zoomModel.range.max),
        zoomSource: this.activeSegment.kind,
        zoomRange: { min: this.zoomModel.range.min, max: this.zoomModel.range.max, step: this.zoomModel.range.step ?? 0.01 },
      });
      void this.discoverCameraProfiles(profile);
      if (requestedZoom != null) await this.setZoom(requestedZoom);
    } catch (error) {
      if (request === this.cameraRequest && !this.isDestroyed()) this.reportCameraError(error);
    } finally {
      if (wasScanning && request === this.cameraRequest) this.scheduleFrame();
    }
  }

  stopCamera(): this {
    this.cameraRequest += 1;
    this.cancelFrame();
    stopStream(this.stream);
    this.stream = null;
    this.track = null;
    if (this.refs) this.refs.video.srcObject = null;
    if (
      this.state.cameraId !== null
      || this.state.cameraLabel !== null
      || this.state.cameraError !== null
      || this.state.torch
      || this.state.torchSupported
    ) this.patchState({ cameraId: null, cameraLabel: null, cameraError: null, torch: false, torchSupported: false });
    return this;
  }

  async selectCamera(deviceId: string): Promise<void> { this.closeCameraMenu(); await this.startCamera(deviceId); }

  async setTorch(enabled: boolean): Promise<boolean> {
    this.assertAlive();
    if (!this.track || !this.state.torchSupported) return false;
    try {
      await applyTorchConstraint(this.track, enabled);
      this.patchState({ torch: enabled });
      return true;
    } catch (error) {
      this.reportCameraError(error);
      return false;
    }
  }

  setHandedness(handedness: ScannerHandedness): this {
    this.assertAlive();
    persistHandedness(handedness);
    if (this.state.handedness !== handedness) this.patchState({ handedness });
    this.syncPresentationState();
    return this;
  }

  toggleHandedness(): void { this.setHandedness(this.state.handedness === "right" ? "left" : "right"); }

  async setZoom(value: number): Promise<number> {
    this.assertAlive();
    const range = this.zoomModel.range;
    const step = range.step && range.step > 0 ? range.step : 0.01;
    const requested = clamp(range.min + Math.round((value - range.min) / step) * step, range.min, range.max);
    const segment = logicalToSegment(requested, this.zoomModel);
    if (segment.deviceId && segment.deviceId !== this.state.cameraId) {
      await this.startCamera(segment.deviceId, requested);
      return this.state.zoom;
    }
    this.activeSegment = segment;
    if (segment.kind === "hardware" && this.track) {
      try {
        await this.track.applyConstraints({ advanced: [{ zoom: logicalToNativeZoom(requested, segment) } as MediaTrackConstraintSet] });
        this.patchState({ zoomSource: "hardware" });
      } catch {
        this.patchState({ zoomSource: "software" });
      }
    } else {
      this.patchState({ zoomSource: "software" });
    }
    this.patchState({ zoom: requested });
    return requested;
  }

  resetRoi(): this {
    const { width, height } = this.surface.stage;
    this.updateRoi(defaultCenteredRoi({ width, height }));
    return this;
  }

  setStageSize(width: number, height: number): void {
    this.patchSurface({ stage: { width, height } });
    const current = this.state.roi;
    if (!current.x && !current.y) this.resetRoi();
    else this.updateRoi(current);
  }

  feedPointerDown(pointerId: number, point: Point, pointerType = "mouse", ctrlKey = false): void {
    if (!this.canInteract()) return;
    const buildInfo = this.buildInfoGesture.begin(pointerId, pointerType, ctrlKey, this.state.roi);
    if (buildInfo.suppress) {
      this.cancelPendingTouchScan();
      if (buildInfo.reveal) this.revealBuildInfo(buildInfo.restoreRoi);
      return;
    }
    if (pointerType === "touch") {
      this.pendingTouchPointers.set(pointerId, point);
      this.pendingTouchTimer ??= setTimeout(() => this.flushPendingTouchScan(), TOUCH_GESTURE_GRACE_MS);
      return;
    }
    this.beginFeedPointer(pointerId, point);
  }

  private beginFeedPointer(pointerId: number, point: Point): void {
    this.pointers.set(pointerId, point);
    if (this.pointers.size === 1) {
      this.gesture = { primaryId: pointerId, mode: "scan", dragOffset: { x: 0, y: 0 } };
      this.updateRoi({ ...this.state.roi, x: point.x, y: point.y });
      this.passiveZoomScan = false;
      this.patchSurface({ focusPulse: this.surface.focusPulse + 1 });
      void this.focusAt(point);
      this.beginScan(this.state.roi);
    } else {
      this.gesture = { primaryId: pointerId, mode: "pinch", dragOffset: { x: 0, y: 0 } };
      this.updatePinch();
    }
  }

  feedPointerMove(pointerId: number, point: Point): void {
    if (this.pendingTouchPointers.has(pointerId)) {
      this.pendingTouchPointers.set(pointerId, point);
      return;
    }
    if (!this.pointers.has(pointerId)) return;
    this.pointers.set(pointerId, point);
    if (this.pointers.size >= 2 || this.gesture?.mode === "pinch") this.updatePinch();
    else if (this.gesture?.mode === "scan") this.updateRoi({
      ...this.state.roi,
      x: point.x + this.gesture.dragOffset.x,
      y: point.y + this.gesture.dragOffset.y,
    });
  }

  dialPointerDown(pointerId: number, clientX: number, clientY: number, rect: DOMRect): void {
    if (!this.canInteract()) return;
    this.dialPointerId = pointerId;
    if (!this.scanOwned && this.pointers.size === 0) {
      this.passiveZoomScan = true;
      this.beginScan(defaultCenteredRoi(this.surface.stage));
    }
    void this.updateDialFromPointer(clientX, clientY, rect);
  }

  dialPointerMove(pointerId: number, clientX: number, clientY: number, rect: DOMRect): void {
    if (this.dialPointerId === pointerId) void this.updateDialFromPointer(clientX, clientY, rect);
  }

  pointerUp(pointerId: number): void {
    if (this.buildInfoGesture.end(pointerId)) return;
    if (this.pendingTouchPointers.has(pointerId)) this.flushPendingTouchScan();
    if (this.dialPointerId === pointerId) this.dialPointerId = null;
    this.pointers.delete(pointerId);
    if (this.gesture?.mode === "pinch" && this.pointers.size === 1) {
      const remaining = this.pointers.entries().next().value as [number, Point] | undefined;
      if (remaining) {
        this.gesture = {
          primaryId: remaining[0],
          mode: "scan",
          dragOffset: { x: this.state.roi.x - remaining[1].x, y: this.state.roi.y - remaining[1].y },
        };
        return;
      }
    }
    if (!this.pointers.size && this.dialPointerId == null) { this.gesture = null; this.endScan(true); }
  }

  pointerCancel(pointerId: number): void {
    if (this.buildInfoGesture.end(pointerId)) return;
    if (this.pendingTouchPointers.delete(pointerId)) {
      if (this.pendingTouchPointers.size === 0) this.clearPendingTouchTimer();
      return;
    }
    if (this.dialPointerId === pointerId) this.dialPointerId = null;
    this.pointers.delete(pointerId);
    if (!this.pointers.size && this.dialPointerId == null) { this.gesture = null; this.endScan(false); }
  }

  private flushPendingTouchScan(): void {
    this.clearPendingTouchTimer();
    const pending = [...this.pendingTouchPointers];
    this.pendingTouchPointers.clear();
    for (const [pointerId, point] of pending) this.beginFeedPointer(pointerId, point);
  }

  private cancelPendingTouchScan(): void {
    this.clearPendingTouchTimer();
    this.pendingTouchPointers.clear();
  }

  private clearPendingTouchTimer(): void {
    if (this.pendingTouchTimer == null) return;
    clearTimeout(this.pendingTouchTimer);
    this.pendingTouchTimer = null;
  }

  private revealBuildInfo(restoreRoi: Roi | null): void {
    this.endScan(false);
    this.pointers.clear();
    this.gesture = null;
    if (restoreRoi) this.updateRoi(restoreRoi);
    this.setStatus({ tone: "neutral", text: formatBuildInfo("seek-qr-svelte"), layout: "diagnostic" });
  }

  handleWheel(deltaY: number): void {
    if (!this.canInteract()) return;
    const span = this.state.zoomRange.max - this.state.zoomRange.min;
    void this.setZoom(this.state.zoom - Math.sign(deltaY) * Math.max(0.05, span / 40));
  }

  handleKey(key: string, shiftKey = false): boolean {
    if (!this.canInteract()) return false;
    const step = shiftKey ? 20 : 8;
    if (["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(key)) {
      const dx = key === "ArrowLeft" ? -step : key === "ArrowRight" ? step : 0;
      const dy = key === "ArrowUp" ? -step : key === "ArrowDown" ? step : 0;
      this.updateRoi({ ...this.state.roi, x: this.state.roi.x + dx, y: this.state.roi.y + dy });
      return true;
    }
    if (["+", "="].includes(key)) { void this.setZoom(this.state.zoom + (this.state.zoomRange.step || 0.1) * 5); return true; }
    if (key === "-") { void this.setZoom(this.state.zoom - (this.state.zoomRange.step || 0.1) * 5); return true; }
    if (key === "Enter") { this.beginScan(); queueMicrotask(() => this.endScan(true)); return true; }
    return false;
  }

  private patchState(patch: Partial<ScannerState<TValue>>): void {
    this.state = { ...this.state, ...patch };
    const snapshot = this.getState();
    for (const listener of this.stateListeners) listener(snapshot);
    this.dispatchEvent(new CustomEvent("statechange", { detail: snapshot }));
  }

  private patchSurface(patch: Partial<ScannerSurfaceState>): void {
    this.surface = { ...this.surface, ...patch };
    const snapshot = this.getSurfaceState();
    for (const listener of this.surfaceListeners) listener(snapshot);
  }

  private patchDialog(patch: Partial<NonNullable<ScannerSurfaceState["dialog"]>>): void {
    if (!this.surface.dialog) return;
    this.patchSurface({ dialog: { ...this.surface.dialog, ...patch } });
    this.syncPresentationState();
  }

  private updateRoi(roi: Roi): void {
    const { width, height } = this.surface.stage;
    const next = width && height ? clampRoi(roi, { width, height }) : roi;
    if (this.scanOwned && !this.passiveZoomScan) this.scanRoi = next;
    this.surface = { ...this.surface, roi: next };
    this.patchState({ roi: next });
    this.patchSurface({ roi: next });
    this.dispatchEvent(new CustomEvent("roichange", { detail: next }));
  }

  private updatePinch(): void {
    const points = [...this.pointers.values()];
    if (points.length < 2) return;
    const frame = pinchZoneFrame(points[0]!, points[1]!);
    this.updateRoi({ x: frame.centerX, y: frame.centerY, size: frame.side });
  }

  private canInteract(): boolean {
    return this.state.lifecycle === "open" && !this.state.inputLocked;
  }

  private actionPromptActions(): readonly PresentedScannerAction[] {
    return orderPresentedActions(mapScannerActionControls(this.actionControls), this.state.handedness);
  }

  private dialogPromptActions(): readonly PresentedScannerAction[] {
    const record = this.dialogRecord;
    if (!record) return [];
    const confirming = isDeleteConfirming(record.deleteStep);
    return orderPresentedActions(mapDialogActionGroups(record.definition), this.state.handedness).map((action) => (
      action.id === record.right?.id && action.tone === "delete"
        ? {
            ...action,
            label: record.deleteStep === "idle" ? action.label : CONFIRM_DELETE_LABEL,
            promptLabel: record.deleteStep === "idle" ? action.promptLabel : CONFIRM_DELETE_LABEL,
            disabled: confirming,
          }
        : action
    ));
  }

  private syncPresentationState(): void {
    const active = this.dialogRecord ? this.dialogPresentation : this.actionPresentation;
    const presentationActions = this.dialogRecord ? this.dialogPromptActions() : this.actionPromptActions();
    const promptActions = this.dialogRecord
      ? (this.dialogPresentation?.mirrorActionsInPrompt ? presentationActions : [])
      : (this.actionPresentation.mirrorActionsInPrompt && this.state.status ? presentationActions : []);
    const presentationLocked = active?.interaction === "locked-glass";
    const inputLocked = this.hostInputLocked || presentationLocked;
    if (inputLocked) this.endScan(false);
    this.patchSurface({
      actions: this.dialogRecord ? this.surface.actions : this.actionControls,
      promptActions,
      interactionGlass: presentationLocked && presentationActions.length > 0,
    });
    if (this.state.inputLocked !== inputLocked) this.patchState({ inputLocked });
  }

  private beginScan(roi: Roi = this.state.roi): void {
    if (!this.canInteract()) return;
    this.scanRoi = { ...roi };
    if (this.scanOwned) {
      this.patchSurface({ scanning: true, roi: this.scanRoi });
      return;
    }
    this.scanOwned = true;
    this.liveDecoded = null;
    this.patchSurface({ scanning: true, roi: this.scanRoi, code: { code: null, state: "preview" } });
    this.dispatchEvent(new Event("scanstart"));
    this.scheduleFrame();
  }

  private endScan(commit: boolean): void {
    if (!this.scanOwned) return;
    this.scanOwned = false;
    const completedRoi = this.scanRoi ?? this.state.roi;
    this.scanRoi = null;
    this.passiveZoomScan = false;
    this.cancelFrame();
    const payload = this.liveDecoded;
    this.liveDecoded = null;
    this.patchSurface({ scanning: false, roi: this.state.roi, code: payload ? { code: payload, state: "preview" } : { code: null, state: "idle" } });
    if (commit && payload != null) void this.deliver(payload, {
      source: "camera",
      cameraId: this.state.cameraId ?? undefined,
      zoom: this.state.zoom,
      roi: completedRoi,
    });
    this.dispatchEvent(new CustomEvent("scanend", { detail: { committed: Boolean(commit && payload != null), payload } }));
  }

  private scheduleFrame(): void {
    if (!this.scanOwned || this.frameHandle != null || !this.refs) return;
    const video = this.refs.video as VideoFrameVideo;
    if (video.requestVideoFrameCallback) {
      this.frameKind = "video";
      this.frameHandle = video.requestVideoFrameCallback((now) => { this.frameHandle = null; void this.decodeFrame(now); });
    } else {
      this.frameKind = "animation";
      this.frameHandle = requestAnimationFrame((now) => { this.frameHandle = null; void this.decodeFrame(now); });
    }
  }

  private cancelFrame(): void {
    if (this.frameHandle == null) return;
    const video = this.refs?.video as VideoFrameVideo | undefined;
    if (this.frameKind === "video" && video?.cancelVideoFrameCallback) video.cancelVideoFrameCallback(this.frameHandle);
    if (this.frameKind === "animation") cancelAnimationFrame(this.frameHandle);
    this.frameHandle = null;
    this.frameKind = null;
  }

  private async decodeFrame(now: number): Promise<void> {
    if (!this.scanOwned || !this.refs) return;
    if (this.decoding || now - this.lastDecodeAt < TARGET_SCAN_INTERVAL_MS) { this.scheduleFrame(); return; }
    const video = this.refs.video;
    if (video.readyState < HTMLMediaElement.HAVE_CURRENT_DATA || !video.videoWidth || !video.videoHeight) { this.scheduleFrame(); return; }
    this.decoding = true;
    this.lastDecodeAt = now;
    const stage = this.surface.stage;
    const softwareZoom = this.state.zoomSource === "software" ? this.state.zoom : 1;
    const roi = padRoiPixels(
      coverRectToVideoRoi(roiToRect(this.scanRoi ?? this.state.roi), stage, { width: video.videoWidth, height: video.videoHeight }, softwareZoom),
      video.videoWidth,
      video.videoHeight,
      ROI_PADDING_RATIO,
    );
    try {
      this.decodeAttempt += 1;
      let payload = await this.decoder.decode({ video, roi, tryHarder: this.decodeAttempt % TRY_HARDER_EVERY === 0 });
      if (!payload) {
        this.consecutiveMisses += 1;
        if (this.consecutiveMisses >= ANGLED_FALLBACK_AFTER_MISSES && now - this.lastAngleFallbackAt >= ANGLED_FALLBACK_INTERVAL_MS) {
          this.lastAngleFallbackAt = now;
          payload = await this.decoder.decode({
            video,
            roi,
            tryHarder: true,
            rotation: ROTATION_FALLBACK[this.decodeAttempt % ROTATION_FALLBACK.length]!,
            maxLongEdge: 960,
          });
        }
      }
      if (payload != null) {
        this.liveDecoded = payload;
        this.consecutiveMisses = 0;
        this.patchSurface({ code: { code: payload, state: "preview" } });
        this.dispatchEvent(new CustomEvent("scanpreview", { detail: { payload } }));
      }
    } finally {
      this.decoding = false;
      this.scheduleFrame();
    }
  }

  private async deliver(payload: string, context: ScanContext): Promise<ScanResult<TValue>> {
    const result = await this.pipeline.emit(payload, context);
    this.patchState({ lastResult: result, status: null });
    this.patchSurface({
      resultText: `QR ${payload} scanned successfully.`,
      code: { code: payload, state: "unknown" },
    });
    return result;
  }

  private async discoverCameraProfiles(seed: CameraProfile): Promise<void> {
    if (!this.mediaDevices || !this.track) return;
    const profiles = await probeCameras(this.mediaDevices, [seed]);
    if (!this.track || this.isDestroyed()) return;
    this.profiles = profiles;
    this.zoomModel = buildUnifiedModel(profiles, {
      allowSwitching: this.options.camera?.allowSwitching ?? true,
      primaryDeviceId: this.state.cameraId ?? undefined,
    });
    this.patchState({ zoomRange: { min: this.zoomModel.range.min, max: this.zoomModel.range.max, step: this.zoomModel.range.step ?? 0.01 } });
  }

  private async updateDialFromPointer(clientX: number, clientY: number, rect: DOMRect): Promise<void> {
    const leftHanded = this.state.handedness === "left";
    const centerX = leftHanded ? rect.left : rect.right;
    const centerY = rect.bottom;
    const horizontal = leftHanded ? centerX - clientX : clientX - centerX;
    const raw = Math.atan2(centerY - clientY, horizontal);
    const angle = clamp(raw < 0 ? raw + Math.PI * 2 : raw, Math.PI / 2, Math.PI);
    await this.setZoom(dialAngleToZoom(angle, this.state.zoomRange));
  }

  private async focusAt(point: Point): Promise<void> {
    if (!this.track) return;
    const { width, height } = this.surface.stage;
    if (!width || !height) return;
    await requestFocusExposure(this.track, { x: clamp(point.x / width, 0, 1), y: clamp(point.y / height, 0, 1) });
  }

  private reportCameraError(error: unknown): void {
    const message = error instanceof Error ? error.message : String(error);
    this.patchState({ cameraError: message });
    this.dispatchEvent(new CustomEvent("cameraerror", { detail: { error, message } }));
  }

  private assertAlive(): void { if (this.isDestroyed()) throw new LifecycleError(); }
  private isDestroyed(): boolean { return this.state.lifecycle === "destroyed"; }
}

export function createSvelteScannerRuntime<TValue = string>(
  options: ScannerOptions<TValue> = {},
): SvelteScannerRuntime<TValue> {
  return new SvelteScannerRuntime(options);
}
