<script lang="ts">
  import { zoomToDialAngle } from "../../../src/camera/zoom";
  import type { ScannerState } from "../../../src/core/types";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";

  let { runtime, state }: {
    runtime: SvelteScannerRuntime<unknown>;
    state: Readonly<ScannerState<unknown>>;
  } = $props();

  let dial: HTMLDivElement;
  const formatZoom = (value: number) => `${Number.isInteger(value) ? value.toFixed(0) : value.toFixed(1)}×`;
  let angle = $derived(zoomToDialAngle(state.zoom, state.zoomRange));
  let base = $derived({ x: 100 + 10 * Math.cos(angle), y: 100 - 10 * Math.sin(angle) });
  let tip = $derived({ x: 100 + 104 * Math.cos(angle), y: 100 - 104 * Math.sin(angle) });
  let progress = $derived(state.zoomRange.max > state.zoomRange.min
    ? ((state.zoom - state.zoomRange.min) / (state.zoomRange.max - state.zoomRange.min)) * 100
    : 0);

  function down(event: PointerEvent) {
    event.preventDefault();
    dial.setPointerCapture?.(event.pointerId);
    runtime.dialPointerDown(event.pointerId, event.clientX, event.clientY, dial.getBoundingClientRect());
  }
</script>

<div class="qr-scanner__dial-shell">
  <div
    bind:this={dial}
    class="qrs-dial qr-scanner__dial"
    role="slider"
    tabindex="0"
    aria-label={`Camera zoom (${state.zoomSource} zoom)`}
    aria-valuemin={state.zoomRange.min}
    aria-valuemax={state.zoomRange.max}
    aria-valuenow={state.zoom}
    aria-valuetext={formatZoom(state.zoom)}
    aria-disabled={state.inputLocked}
    onpointerdown={down}
    onpointermove={(event) => runtime.dialPointerMove(event.pointerId, event.clientX, event.clientY, dial.getBoundingClientRect())}
    onpointerup={(event) => runtime.pointerUp(event.pointerId)}
    onpointercancel={(event) => runtime.pointerCancel(event.pointerId)}
    onkeydown={(event) => {
      if (runtime.handleKey(event.key, event.shiftKey)) {
        event.preventDefault();
        event.stopPropagation();
      }
    }}
  >
    <span class="qr-scanner__dial-glass" aria-hidden="true"></span>
    <svg class="qr-scanner__dial-face" viewBox="0 0 100 100" aria-hidden="true">
      <defs>
        <linearGradient id="qr-dial-progress-gradient" x1="0%" y1="100%" x2="100%" y2="0%">
          <stop class="qr-scanner__dial-fill-from" offset="0%" stop-opacity=".72"></stop>
          <stop class="qr-scanner__dial-fill-to" offset="100%" stop-opacity=".9"></stop>
        </linearGradient>
        <linearGradient id="qr-dial-needle-gradient" gradientUnits="userSpaceOnUse" x1={base.x} y1={base.y} x2={tip.x} y2={tip.y}>
          <stop class="qr-scanner__dial-needle-light" offset="0%" stop-opacity=".04"></stop>
          <stop class="qr-scanner__dial-needle-light" offset="58%" stop-opacity=".34"></stop>
          <stop class="qr-scanner__dial-needle-light" offset="100%" stop-opacity=".95"></stop>
        </linearGradient>
        <linearGradient id="qr-dial-scale-fade" gradientUnits="userSpaceOnUse" x1="13" y1="100" x2="100" y2="13">
          <stop offset="0%" stop-color="#fff" stop-opacity="0"></stop><stop offset="5%" stop-color="#fff" stop-opacity="1"></stop>
          <stop offset="95%" stop-color="#fff" stop-opacity="1"></stop><stop offset="100%" stop-color="#fff" stop-opacity="0"></stop>
        </linearGradient>
        <mask id="qr-dial-scale-mask" maskUnits="userSpaceOnUse" x="0" y="0" width="112" height="112">
          <rect x="0" y="0" width="112" height="112" fill="url(#qr-dial-scale-fade)"></rect>
        </mask>
      </defs>
      <g mask="url(#qr-dial-scale-mask)">
        <path class="qr-scanner__dial-track-border" d="M 13 100 A 87 87 0 0 1 100 13"></path>
        <path class="qr-scanner__dial-track" d="M 13 100 A 87 87 0 0 1 100 13"></path>
        <path class="qr-scanner__dial-progress-border" d="M 13 100 A 87 87 0 0 1 100 13" pathLength="100" stroke-dasharray={`${progress} 100`}></path>
        <path class="qr-scanner__dial-progress" d="M 13 100 A 87 87 0 0 1 100 13" pathLength="100" stroke-dasharray={`${progress} 100`}></path>
      </g>
      <text class="qr-scanner__dial-label qr-scanner__dial-label--min" x="14.3" y="85.3">{formatZoom(state.zoomRange.min)}</text>
      <text class="qr-scanner__dial-label qr-scanner__dial-label--max" x="85.3" y="14.3">{formatZoom(state.zoomRange.max)}</text>
      <line class="qrs-dial__needle qr-scanner__dial-needle" x1={base.x} y1={base.y} x2={tip.x} y2={tip.y}></line>
      <circle class="qr-scanner__dial-pivot-edge" cx={base.x} cy={base.y} r="2.9"></circle>
      <circle class="qr-scanner__dial-pivot" cx={base.x} cy={base.y} r="1.7"></circle>
    </svg>
    <output class="qrs-dial__value" hidden>{formatZoom(state.zoom)}</output>
  </div>
  <button
    type="button"
    class="qr-scanner__handedness-toggle"
    style={`--qr-pivot-x: ${base.x}%; --qr-pivot-y: ${base.y}%`}
    aria-label={state.handedness === "left" ? "Switch to right-handed controls" : "Switch to left-handed controls"}
    aria-pressed={state.handedness === "left"}
    onclick={() => runtime.toggleHandedness()}
  ></button>
</div>
