<script lang="ts">
  import { onDestroy } from "svelte";
  import { copyableCodePayload, copyCodeToClipboard } from "../../../src/core/code-copy";
  import type { ScannerState } from "../../../src/core/types";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";
  import type { ScannerSurfaceState } from "../runtime/types";
  import CameraMenu from "./CameraMenu.svelte";

  let { runtime, state: scannerState, surface }: {
    runtime: SvelteScannerRuntime<unknown>;
    state: Readonly<ScannerState<unknown>>;
    surface: Readonly<ScannerSurfaceState>;
  } = $props();

  let copiedCode = $state<string | null>(null);
  let copyFeedbackTimer: ReturnType<typeof setTimeout> | null = null;
  const copyablePayload = $derived(copyableCodePayload(surface.code));
  const copyConfirmed = $derived(copyablePayload !== null && copiedCode === copyablePayload);

  async function copyCode(): Promise<void> {
    const presentation = surface.code;
    if (!await copyCodeToClipboard(presentation)) return;
    if (copyableCodePayload(surface.code) !== presentation.code) return;
    copiedCode = presentation.code;
    if (copyFeedbackTimer !== null) clearTimeout(copyFeedbackTimer);
    copyFeedbackTimer = setTimeout(() => {
      copiedCode = null;
      copyFeedbackTimer = null;
    }, 1200);
  }

  onDestroy(() => {
    if (copyFeedbackTimer !== null) clearTimeout(copyFeedbackTimer);
  });
</script>

<div class="qrs-topbar qr-scanner__topbar">
  <div class="qr-scanner__camera-picker">
    <button
      type="button"
      class:is-open={surface.cameraMenuOpen}
      class="qrs-camera qr-scanner__camera-button"
      aria-label="Choose camera"
      aria-haspopup="menu"
      aria-expanded={surface.cameraMenuOpen}
      title="Choose camera; double-tap to cycle"
      onclick={() => runtime.toggleCameraMenu()}
    >
      <span class="qr-scanner__camera-icon" aria-hidden="true"></span>
    </button>
    <CameraMenu {runtime} cameras={surface.cameras} open={surface.cameraMenuOpen} />
  </div>
  <button
    type="button"
    class="qrs-torch qr-scanner__torch"
    aria-label="Toggle flashlight"
    aria-pressed={scannerState.torch}
    disabled={!scannerState.torchSupported}
    onclick={() => runtime.setTorch(!scannerState.torch)}
  ><span class="qr-scanner__torch-icon" aria-hidden="true"></span></button>
  <button
    type="button"
    class:is-preview={surface.code.state === "preview"}
    class:is-known={surface.code.state === "known"}
    class:is-unknown={surface.code.state === "unknown"}
    class="qr-scanner__code"
    disabled={copyablePayload === null}
    aria-pressed="false"
    aria-label={copyConfirmed ? "QR code copied" : copyablePayload ? `Copy QR code ${copyablePayload}` : "QR code unavailable"}
    data-copy-state={copyConfirmed ? "copied" : undefined}
    onclick={copyCode}
  >
    <span class="qr-scanner__code-icon" aria-hidden="true">
      <span class="qr-scanner__code-icon-base"></span>
      <span class="qr-scanner__code-icon-glow"></span>
    </span>
    <span class="qr-scanner__code-text">{surface.code.code ?? "------"}</span>
  </button>
  <button type="button" class="qrs-close qr-scanner__close" aria-label="Close QR scanner" onclick={() => runtime.requestClose()}>✕</button>
</div>
