<script lang="ts">
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";

  let { runtime, cameras, open }: {
    runtime: SvelteScannerRuntime<unknown>;
    cameras: readonly MediaDeviceInfo[];
    open: boolean;
  } = $props();
</script>

<div class="qr-scanner__camera-menu" role="menu" aria-label="Rear cameras" hidden={!open}>
  {#if cameras.length}
    {#each cameras as camera, index (camera.deviceId)}
      <button type="button" role="menuitem" onclick={() => runtime.selectCamera(camera.deviceId)}>
        {camera.label || `Camera ${index + 1}`}
      </button>
    {/each}
  {:else}
    <span>Default rear camera</span>
  {/if}
</div>
