<script lang="ts">
  import { CONFIRM_DELETE_LABEL } from "../../../src/core/delete-confirmation";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";
  import type { ScannerSurfaceState } from "../runtime/types";
  import DeleteGlyph from "./DeleteGlyph.svelte";

  let { runtime, surface }: {
    runtime: SvelteScannerRuntime<unknown>;
    surface: Readonly<ScannerSurfaceState>;
  } = $props();

  let deleting = $derived(surface.dialog?.right?.tone === "delete");
  let deleteLabel = $derived(
    surface.dialog?.deleteStep === "armed" || surface.dialog?.deleteStep === "confirming"
      ? CONFIRM_DELETE_LABEL
      : surface.actions.accept?.label,
  );
</script>

<button
  type="button"
  class="qr-scanner__jump"
  hidden={!surface.actions.jump}
  disabled={surface.actions.jump?.disabled}
  aria-label={surface.actions.jump?.label}
  onclick={() => runtime.triggerAction("jump")}
><span class="qr-scanner__jump-icon" aria-hidden="true"></span></button>

<button
  type="button"
  class:is-delete={deleting}
  class:is-deleting={surface.dialog?.deleteAnimating}
  class="qr-scanner__accept"
  data-delete-step={surface.dialog?.deleteStep}
  hidden={!surface.actions.accept}
  disabled={surface.actions.accept?.disabled || surface.dialog?.deleteAnimating}
  aria-label={deleteLabel}
  onclick={() => runtime.triggerAction("accept")}
  onanimationend={(event) => {
    if (event.animationName === "job-delete-lid" && (event.target as Element).classList.contains("job-delete-glyph__lid")) {
      runtime.completeDeleteAnimation();
    }
  }}
>
  <span class="qr-scanner__accept-check" aria-hidden="true">✓</span>
  <DeleteGlyph />
</button>

<button
  type="button"
  class="qr-scanner__cancel"
  hidden={!surface.actions.cancel}
  disabled={surface.actions.cancel?.disabled}
  aria-label={surface.actions.cancel?.label}
  onclick={() => runtime.triggerAction("cancel")}
>✕</button>
