<script lang="ts">
  import { onMount, type Snippet } from "svelte";
  import type { ScannerState } from "../../../src/core/types";
  import {
    radialControlGeometryCssText,
    readRadialControlSafeAreaInsets,
    resolveRadialControlGeometry,
    type RadialControlSafeAreaInsets,
  } from "../../../src/ui/radial-geometry";
  import type { SvelteScannerRuntime } from "../runtime/scanner-runtime";
  import type { ScannerSurfaceState } from "../runtime/types";

  let { runtime, state: scannerState, surface, children }: {
    runtime: SvelteScannerRuntime<unknown>;
    state: Readonly<ScannerState<unknown>>;
    surface: Readonly<ScannerSurfaceState>;
    children: Snippet;
  } = $props();

  let stage: HTMLDivElement;
  let video: HTMLVideoElement;
  let safeArea = $state<RadialControlSafeAreaInsets>({ top: 0, right: 0, bottom: 0, left: 0 });
  let radialGeometryStyle = $derived(
    surface.stage.width > 0 && surface.stage.height > 0
      ? radialControlGeometryCssText(resolveRadialControlGeometry(surface.stage.width, surface.stage.height, safeArea))
      : undefined,
  );

  const point = (event: PointerEvent) => {
    const rect = stage.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  onMount(() => {
    runtime.attachSurface({ video });
    const measure = () => {
      const rect = stage.getBoundingClientRect();
      safeArea = readRadialControlSafeAreaInsets(stage);
      runtime.setStageSize(rect.width, rect.height);
    };
    measure();
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure);
    observer?.observe(stage);
    if (!observer) window.addEventListener("resize", measure);
    return () => {
      observer?.disconnect();
      if (!observer) window.removeEventListener("resize", measure);
      runtime.detachSurface();
    };
  });

  function down(event: PointerEvent) {
    if ((event.target as Element).closest(".qrs-topbar, .qr-scanner__dial-shell, .qrs-result, .qrs-status, .qrs-dialog, .qr-scanner__jump, .qr-scanner__accept, .qr-scanner__cancel, .qr-scanner__handedness-toggle")) return;
    event.preventDefault();
    stage.setPointerCapture?.(event.pointerId);
    runtime.feedPointerDown(event.pointerId, point(event), event.pointerType, event.ctrlKey);
  }
</script>

<div
  bind:this={stage}
  class="qrs-stage qr-scanner__camera"
  role="group"
  aria-label="Camera scan surface"
  style={radialGeometryStyle}
  onpointerdown={down}
  onpointermove={(event) => runtime.feedPointerMove(event.pointerId, point(event))}
  onpointerup={(event) => runtime.pointerUp(event.pointerId)}
  onpointercancel={(event) => runtime.pointerCancel(event.pointerId)}
>
  <div class="qrs-software-zoom" style:transform={scannerState.zoomSource === "software" ? `scale(${Math.max(1, scannerState.zoom)})` : undefined}>
    <video bind:this={video} class="qrs-video" autoplay playsinline muted aria-label="Camera preview"></video>
  </div>
  <div class="qrs-feed-shade" aria-hidden="true"></div>
  <div
    class="qrs-zone qr-scanner__hold-zone"
    aria-hidden="true"
    hidden={!surface.scanning}
    data-scanning={surface.scanning}
    data-focus-pulse={surface.focusPulse > 0 ? (surface.focusPulse % 2 ? "odd" : "even") : undefined}
    style={`left:${surface.roi.x}px;top:${surface.roi.y}px;width:${surface.roi.size}px;height:${surface.roi.size}px`}
  ></div>
  <div class="qrs-interaction-glass" aria-hidden="true" hidden={!surface.interactionGlass}></div>
  {@render children()}
</div>
