<script lang="ts">
  import { onMount, tick, untrack } from "svelte";
  import type { QrDecoder } from "../../src/decoder/types";
  import type { CameraOptions, ScannerHandedness, ScannerOptions } from "../../src/core/types";
  import "../../src/ui/scanner.css";
  import ActionControls from "./components/ActionControls.svelte";
  import CameraStage from "./components/CameraStage.svelte";
  import PromptStack from "./components/PromptStack.svelte";
  import RadialDial from "./components/RadialDial.svelte";
  import TopControls from "./components/TopControls.svelte";
  import { createSvelteScannerRuntime, type SvelteScannerRuntime } from "./runtime/scanner-runtime";

  interface Props extends ScannerOptions<unknown> {
    runtime?: SvelteScannerRuntime<unknown>;
    autoOpen?: boolean;
    camera?: CameraOptions;
    decoder?: QrDecoder;
    handedness?: ScannerHandedness;
  }

  let {
    runtime: suppliedRuntime,
    autoOpen = true,
    camera,
    decoder,
    mediaDevices,
    handedness,
    normalizePayload,
    handler,
    onResult,
    historyLimit,
  }: Props = $props();

  const ownsRuntime = untrack(() => !suppliedRuntime);
  const runtime = untrack(() => suppliedRuntime ?? createSvelteScannerRuntime({
    camera,
    decoder,
    mediaDevices,
    handedness,
    normalizePayload,
    handler,
    onResult,
    historyLimit,
  }));
  let root: HTMLDivElement;
  let scannerState = $state(runtime.getState());
  let surface = $state(runtime.getSurfaceState());

  const blocksRootGesture = (target: EventTarget | null) => target instanceof Element && Boolean(target.closest([
    ".qrs-topbar",
    ".qrs-result",
    ".qrs-status",
    ".qrs-dialog",
    ".qr-scanner__jump",
    ".qr-scanner__accept",
    ".qr-scanner__cancel",
    ".qr-scanner__handedness-toggle",
    "button",
    "[role='button']",
  ].join(", ")));

  async function positionCameraMenu() {
    if (!surface.cameraMenuOpen || !root) return;
    await tick();
    const menu = root.querySelector<HTMLElement>(".qr-scanner__camera-menu");
    const picker = root.querySelector<HTMLElement>(".qr-scanner__camera-picker");
    const prompt = Array.from(root.querySelectorAll<HTMLElement>(".qrs-dialog, .qrs-status, .qrs-result"))
      .find((element) => !element.hidden);
    if (!menu || !picker) return;
    if (!prompt) { menu.style.removeProperty("top"); return; }
    const gapValue = getComputedStyle(root).getPropertyValue("--qr-stack-gap").trim();
    const amount = Number.parseFloat(gapValue);
    const rootFont = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;
    const gap = Number.isFinite(amount) ? (gapValue.endsWith("rem") ? amount * rootFont : amount) : 12.8;
    menu.style.top = `${Math.max(0, Math.round((prompt.getBoundingClientRect().bottom - picker.getBoundingClientRect().top + gap) * 100) / 100)}px`;
  }

  $effect(() => {
    surface.cameraMenuOpen;
    surface.dialog;
    surface.resultText;
    scannerState.status;
    void positionCameraMenu();
  });

  onMount(() => {
    const unsubscribeState = runtime.subscribeState((value) => { scannerState = value; });
    const unsubscribeSurface = runtime.subscribeSurface((value) => { surface = value; });
    runtime.mount(root);
    if (autoOpen && runtime.getState().lifecycle !== "open") runtime.open();
    return () => {
      unsubscribeState();
      unsubscribeSurface();
      if (ownsRuntime) runtime.destroy();
      else runtime.detachSurface();
    };
  });
</script>

<div
  bind:this={root}
  class:is-left-handed={scannerState.handedness === "left"}
  class="qrs-root qr-scanner"
  data-handedness={scannerState.handedness}
  data-targeting={scannerState.targeting}
  role="dialog"
  aria-modal="true"
  aria-label="QR scanner"
  data-input-locked={scannerState.inputLocked}
  tabindex="0"
  hidden={!surface.visible && scannerState.lifecycle !== "new" && scannerState.lifecycle !== "mounted"}
  onwheel={(event) => { if (!blocksRootGesture(event.target)) { event.preventDefault(); runtime.handleWheel(event.deltaY); } }}
  onkeydown={(event) => { if (!blocksRootGesture(event.target) && runtime.handleKey(event.key, event.shiftKey)) event.preventDefault(); }}
>
  <CameraStage {runtime} state={scannerState} {surface}>
    <TopControls {runtime} state={scannerState} {surface} />
    <PromptStack {runtime} state={scannerState} {surface} />
    <ActionControls {runtime} {surface} />
    <RadialDial {runtime} state={scannerState} />
  </CameraStage>
</div>
